/**
 * KS-1050 (round 2) — PATCH /api/users/me over a 0-row UPDATE must not answer success.
 *
 * Since KS-943, `updateUser` answers `null` when its UPDATE matched 0 rows. The
 * handler answered `success: true` over that null. Round 2 routes the handler
 * through the house helper `updateUserOrThrow` (KS-1052), which refuses with a
 * retryable 503 "<operation> could not be confirmed".
 *
 * WHY THE REAL REPO. Round 1 mocked `userRepo` whole, so a helper-shaped fix
 * would have been tested against a mock of the helper, not the helper's own
 * status and message. Here the real `userRepo` runs over a stateful `../db`
 * stub (the ks1052 pattern): the UPDATE answers `state.updateRowCount` rows, and
 * a 1-row UPDATE is applied to the stored row so the read-back returns what was
 * written. PII columns go through the real subject-DEK encrypt and decrypt with
 * a fixed test DEK; only the DEK store is stubbed.
 *
 * The caller is injected the way `authenticate()` does it: inside
 * `runWithTenantId`, so the repo takes the post-auth path (no pre-auth lookup).
 */
import { describe, it, expect, beforeAll, afterAll, beforeEach, vi } from 'vitest';
import type { AddressInfo } from 'node:net';
import express from 'express';

const USER_ID = 'c1000000-0000-4000-8000-000000001050';
const TENANT_ID = 'b1000000-0000-4000-8000-000000001050';

const state = vi.hoisted(() => ({
  updateRowCount: 1 as 0 | 1,
  row: {} as Record<string, unknown>,
  queries: [] as Array<{ sql: string; params: unknown[]; tenantId?: string }>,
}));

const log = vi.hoisted(() => ({ debug: vi.fn(), info: vi.fn(), warn: vi.fn(), error: vi.fn(), log: vi.fn() }));
vi.mock('../utils/logger', () => ({ logger: log, createLogger: () => log, validateEnv: vi.fn() }));
vi.mock('@secuura/shared/utils/logger', () => ({ logger: log, createLogger: () => log }));

const TEST_DEK = vi.hoisted(() => Buffer.alloc(32, 7));
vi.mock('../services/subjectDeks', () => ({
  subjectDeks: {
    getDek: vi.fn(async () => TEST_DEK),
    getOrCreateDek: vi.fn(async () => TEST_DEK),
  },
}));

vi.mock('../db', () => ({
  isDbAvailable: () => true,
  getPool: () => ({}),
  query: vi.fn(async (sql: string, params: unknown[] = [], tenantId?: string) => {
    state.queries.push({ sql, params, tenantId });
    const update = /^\s*UPDATE\s+users\s+SET\s+(.*)\s+WHERE\s+id\s*=\s*\$\d+\s*$/is.exec(sql);
    if (update) {
      if (state.updateRowCount === 1) {
        for (const clause of update[1].split(/,\s*/)) {
          const m = /^(\w+)\s*=\s*(?:\$(\d+)|NOW\(\))$/.exec(clause.trim());
          if (m) state.row[m[1]] = m[2] ? params[Number(m[2]) - 1] : new Date();
        }
      }
      return { rows: [], rowCount: state.updateRowCount };
    }
    if (/FROM\s+users\s+WHERE\s+id/i.test(sql)) return { rows: [{ ...state.row }], rowCount: 1 };
    return { rows: [], rowCount: 0 };
  }),
}));

vi.mock('../middleware/authenticate', async () => {
  const { runWithTenantId } = await import('@secuura/shared');
  const injectCaller =
    () => (req: express.Request & { user?: unknown }, _res: express.Response, next: express.NextFunction) => {
      (req as { user: unknown }).user = { userId: USER_ID, role: 'USER', tenantId: TENANT_ID };
      runWithTenantId(TENANT_ID, () => next());
    };
  return { authenticate: injectCaller, authenticateAccessOrConnector: injectCaller };
});
vi.mock('../services/session', () => ({ revokeAllUserSessions: vi.fn(async () => 0) }));
vi.mock('../services/password', () => ({
  hashPassword: vi.fn(async () => 'hashed'),
  checkPasswordStrength: vi.fn(() => ({ ok: true })),
  verifyPassword: vi.fn(async () => true),
}));

import { userRoutes } from '../routes/users';
import { errorHandler } from '../middleware/errorHandler';

function seedRow(): Record<string, unknown> {
  return {
    id: USER_ID, email: 'ks1050-profile@example.test', first_name: 'Ada', last_name: 'Lovelace', display_name: null,
    role: 'user', status: 'active', email_verified: true, phone_number: null, phone_verified: false,
    mfa_enabled: false, mfa_secret: null, mfa_backup_codes: null, verification_level: 'basic',
    organization_id: null, tenant_id: TENANT_ID, tenant_slug: null, wallet_address: null, auth_method: 'password',
    external_provider: null, external_id: null, google_id: null, linkedin_id: null, facebook_id: null,
    apple_id: null, github_id: null, microsoft_personal_id: null, metadata: null,
    created_at: new Date(), updated_at: new Date(), last_login_at: null,
  };
}

let server: ReturnType<ReturnType<typeof express>['listen']>;
let baseUrl: string;

beforeAll(async () => {
  const app = express();
  app.use(express.json());
  app.use('/', userRoutes);
  app.use(errorHandler);
  await new Promise<void>((resolve) => {
    server = app.listen(0, '127.0.0.1', () => {
      baseUrl = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
      resolve();
    });
  });
});

afterAll(async () => {
  await new Promise<void>((resolve) => server.close(() => resolve()));
});

beforeEach(() => {
  vi.clearAllMocks();
  state.updateRowCount = 1;
  state.row = seedRow();
  state.queries = [];
});

async function patchMe(body: unknown): Promise<{ status: number; body: any; text: string }> {
  const res = await fetch(`${baseUrl}/me`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  const text = await res.text();
  return { status: res.status, body: JSON.parse(text), text };
}

const updates = () => state.queries.filter((q) => /^\s*UPDATE\s+users/i.test(q.sql));
const readBacksAfterUpdate = () => {
  const i = state.queries.findIndex((q) => /^\s*UPDATE\s+users/i.test(q.sql));
  return i < 0 ? [] : state.queries.slice(i + 1).filter((q) => /FROM\s+users\s+WHERE\s+id/i.test(q.sql));
};

describe('KS-1050 r2 — PATCH /me over a 0-row UPDATE refuses through updateUserOrThrow', () => {
  it('🔴 KS-1050 — a 0-row UPDATE answers 503 "Profile update could not be confirmed", never a not-applied claim', async () => {
    state.updateRowCount = 0;
    const res = await patchMe({ firstName: 'Grace' });
    expect(res.status).toBe(503);
    expect(res.body.success).toBe(false);
    expect(res.body.error.code).toBe('SERVICE_UNAVAILABLE');
    expect(res.body.error.message).toMatch(/^Profile update could not be confirmed\. Please retry/);
    // The helper's docblock forbids asserting the change did not land: null has two causes.
    expect(res.text).not.toMatch(/not applied|matched no row|did not persist/i);
    // The null came from the 0-row arm: one UPDATE issued, and no read-back after it.
    expect(updates()).toHaveLength(1);
    expect(readBacksAfterUpdate()).toHaveLength(0);
  });

  it('🔴 KS-1050 — a 0-row UPDATE never answers success: true, and the success line is not logged', async () => {
    state.updateRowCount = 0;
    const res = await patchMe({ firstName: 'Grace' });
    expect(res.body.success).not.toBe(true);
    expect(log.info).not.toHaveBeenCalledWith('User profile updated', expect.anything());
  });

  it('🔴 KS-1050 — the refusal is the house helper\'s: logged with operation "Profile update" and the columns', async () => {
    state.updateRowCount = 0;
    await patchMe({ firstName: 'Grace' });
    expect(log.error).toHaveBeenCalledWith('User update could not be confirmed — refusing to report success', {
      userId: USER_ID,
      operation: 'Profile update',
      columns: ['firstName'],
    });
  });

  it('KS-1050 control — a 1-row UPDATE answers 200 with the value read back through the real repo', async () => {
    state.updateRowCount = 1;
    const res = await patchMe({ firstName: 'Grace' });
    expect(res.status).toBe(200);
    expect(res.body.success).toBe(true);
    expect(res.body.data.id).toBe(USER_ID);
    expect(res.body.data.firstName).toBe('Grace');
    expect(res.body.data.lastName).toBe('Lovelace');
    // The write went through the real subject-DEK encryption, and the read-back followed it.
    expect(String(state.row.first_name)).toMatch(/^d1:/);
    expect(updates()).toHaveLength(1);
    expect(readBacksAfterUpdate()).toHaveLength(1);
    expect(log.info).toHaveBeenCalledWith('User profile updated', { userId: USER_ID });
  });
});
